function initSidebar() {
    try {
        if (document.getElementById("modern-sidebar")) return;

        // Top Header Creation
        let topHeader = document.createElement("header");
        topHeader.id = "modern-top-header";
        
        let headerLeft = document.createElement("div");
        headerLeft.className = "header-left";
        
        // Add mobile toggle button
        let mobileToggle = document.createElement("button");
        mobileToggle.className = "mobile-sidebar-toggle d-lg-none";
        mobileToggle.innerHTML = "<i class=\"fa-solid fa-bars\"></i>";
        mobileToggle.addEventListener("click", function() {
            document.body.classList.toggle("sidebar-open");
        });
        headerLeft.appendChild(mobileToggle);

        // Grab Logo
        let logoSrc = "/wp-content/themes/fisat2022/assets/fisat-logo.png";
        let logoLink = document.createElement("a");
        logoLink.href = "/";
        logoLink.innerHTML = `<img src="${logoSrc}" alt="FISAT" class="header-logo-img">`;
        headerLeft.appendChild(logoLink);
        
        topHeader.appendChild(headerLeft);

        // Add extra actions (Login/Admissions) to Top Right
        let actionContainer = document.createElement("div");
        actionContainer.className = "header-actions";
        let loginLink = document.querySelector(".btn-primary[href*=\"intranet\"]");
        let admLink = document.querySelector(".btn-admissions");
        
        if(loginLink) actionContainer.appendChild(loginLink.cloneNode(true));
        if(admLink) actionContainer.appendChild(admLink.cloneNode(true));
        topHeader.appendChild(actionContainer);
        
        document.body.insertBefore(topHeader, document.body.firstChild);

        // Sidebar Creation (Navigation only)
        let sidebar = document.createElement("aside");
        sidebar.id = "modern-sidebar";
        
        // Grab Nav Items from #menu-primary-menu
        let primaryMenu = document.getElementById("menu-primary-menu");
        if(primaryMenu) {
            let cloneMenu = primaryMenu.cloneNode(true);
            cloneMenu.id = "sidebar-menu";
            
            const iconMap = {
                "Home": "fa-house",
                "About": "fa-circle-info",
                "Governance": "fa-landmark",
                "Faculty": "fa-chalkboard-user",
                "Administration": "fa-sitemap",
                "Careers": "fa-briefcase",
                "Academics": "fa-graduation-cap",
                "Admissions": "fa-user-plus",
                "Placements": "fa-award",
                "Facilities & Resources": "fa-building",
                "Facilities": "fa-building",
                "Research": "fa-microscope",
                "Library": "fa-book",
                "Campus Life": "fa-users",
                "Industry": "fa-industry",
                "IQAC": "fa-chart-line",
                "NIRF": "fa-ranking-star",
                "UGC Compliance": "fa-file-signature"
            };
            
            let links = cloneMenu.querySelectorAll("a.nav-link, a.dropdown-item");
            links.forEach(link => {
                let span = link.querySelector("span");
                if(span) {
                    let text = span.textContent.trim();
                    if(iconMap[text]) {
                        let icon = document.createElement("i");
                        icon.className = `fa-solid ${iconMap[text]} sidebar-icon`;
                        link.insertBefore(icon, span);
                    }
                }
            });

            let dropdowns = cloneMenu.querySelectorAll(".dropdown-toggle, [data-bs-toggle=\"dropdown\"]");
            dropdowns.forEach(dd => {
                dd.addEventListener("click", function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    let parent = this.parentElement;
                    parent.classList.toggle("open");
                });
            });

            sidebar.appendChild(cloneMenu);
        }

        document.body.insertBefore(sidebar, topHeader.nextSibling);
        document.body.classList.add("has-sidebar");
        
    } catch(err) {
        console.error("Sidebar injection failed:", err);
        let style = document.createElement("style");
        style.innerHTML = "#navBar { display: block !important; }";
        document.head.appendChild(style);
    }
}

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initSidebar);
} else {
    initSidebar();
}
